 void MakeDetailsSelectable(DependencyObject node){
  var panel=node as Panel;if(panel!=null){for(int i=0;i<panel.Children.Count;i++){
   var text=panel.Children[i] as TextBlock;
   if(text!=null){var selectable=new TextBox{IsReadOnly=true,IsReadOnlyCaretVisible=true,TextWrapping=text.TextWrapping,AcceptsReturn=true,Background=Brushes.Transparent,BorderThickness=new Thickness(0),Padding=new Thickness(0),Margin=text.Margin,FontSize=text.FontSize,FontWeight=text.FontWeight,Foreground=Palette.Text,VerticalAlignment=text.VerticalAlignment};
    selectable.SetBinding(TextBox.TextProperty,new Binding("Text"){Source=text,Mode=BindingMode.OneWay});DockPanel.SetDock(selectable,DockPanel.GetDock(text));panel.Children.RemoveAt(i);panel.Children.Insert(i,selectable);
   }else MakeDetailsSelectable(panel.Children[i]);
  }return;}
  var scroll=node as ScrollViewer;if(scroll!=null&&scroll.Content is DependencyObject)MakeDetailsSelectable((DependencyObject)scroll.Content);
  var border=node as Border;if(border!=null&&border.Child!=null)MakeDetailsSelectable(border.Child);
 }
 void AddColumn(DataGrid g,string header,string property,int width){g.Columns.Add(new DataGridTextColumn{Header=header,Binding=new Binding(property){UpdateSourceTrigger=UpdateSourceTrigger.PropertyChanged},Width=width});}
 void OpenDetails(){if(editing==null)return;if(settings.TableOnly){settings.TableOnly=false;settings.FiltersHidden=true;}GrowForDetails();detailsOpen=true;SetPresentation(false);}
