public static class Program {
 [STAThread] public static void Main(string[] args){try{if(args.Length>0&&args[0]=="--apply-update"){Environment.ExitCode=CompanionUpdater.Apply(args);return;}if(args.Contains("--test")){Tests.Run();return;}var app=new Application();var window=new MainWindow();if(args.Contains("--preview")){window.Show();window.Preview(Path.Combine(MainWindow.Home,"preview.png"));window.Close();return;}app.Run(window);}catch(Exception e){File.WriteAllText(Path.Combine(MainWindow.Home,"error.log"),e.ToString());if(!args.Contains("--test"))MessageBox.Show(e.Message,"EQ Legends Achievement Companion");Environment.ExitCode=1;}}
}
